import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.D3GK3dQI.js";const h=JSON.parse('{"title":"ADR-006: Exposure Metric Identity","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/006-metric-labels-expansion.md","filePath":"adrs/006-metric-labels-expansion.md"}'),n={name:"adrs/006-metric-labels-expansion.md"};function r(c,e,d,s,l,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-006-exposure-metric-identity" tabindex="-1">ADR-006: Exposure Metric Identity <a class="header-anchor" href="#adr-006-exposure-metric-identity" aria-label="Permalink to &quot;ADR-006: Exposure Metric Identity&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-07<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The original <code>exposed_route_info</code> labels identified a Service, Gateway, and path, but did not identify the <code>HTTPRoute</code>, listener, hostname, backend namespace, or backend port that produced the relationship. Distinct Gateway API configurations could therefore collapse into the same Prometheus series.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The metric includes these labels:</p><ul><li><code>namespace</code>: HTTPRoute namespace, retained for backward compatibility.</li><li><code>gateway_name</code>: referenced Gateway name.</li><li><code>route_name</code>: HTTPRoute name.</li><li><code>route_namespace</code>: HTTPRoute namespace, included as explicit resource identity.</li><li><code>hostname</code>: effective hostname intersection between the Route and listener; empty when unrestricted.</li><li><code>listener_name</code>: accepting Gateway listener.</li><li><code>http_path</code>: path from an HTTPRoute match, defaulting to <code>/</code>.</li><li><code>service_name</code>: backend Service name.</li><li><code>backend_namespace</code>: explicit backend namespace or the HTTPRoute namespace by default.</li><li><code>backend_port</code>: backend Service port, or an empty string when omitted.</li><li><code>lb_type</code>: <code>internal</code> or <code>external</code>, inferred from the GatewayClass name.</li><li><code>ip_address</code>: first <code>IPAddress</code> from <code>Gateway.status.addresses</code>, or an empty string.</li></ul><p>The mapper emits one series per valid listener, effective hostname, path match, backend reference, and Gateway IP value. Identical series are deduplicated.</p><p>The metric does not enumerate the Pods or EndpointSlices selected by a Service. Backend replica count does not multiply exposure series.</p><h3 id="attachment-rules" tabindex="-1">Attachment Rules <a class="header-anchor" href="#attachment-rules" aria-label="Permalink to &quot;Attachment Rules&quot;">​</a></h3><p>The mapper requires an <code>Accepted=True</code> parent status for the current HTTPRoute generation. It resolves listeners using <code>sectionName</code> and <code>port</code>, HTTP/HTTPS protocol compatibility, <code>allowedRoutes.kinds</code>, namespace selection, and hostname intersection.</p><p>Cross-namespace Service backends require a matching <code>ReferenceGrant</code>. Each backend is evaluated independently, and the referenced Service and port must exist, so one invalid backend does not hide valid backends in the same rule.</p><p>The mapper does not require <code>Gateway Programmed=True</code>. This allows configured and accepted exposure relationships to remain visible while infrastructure is provisioning.</p><h3 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h3><p>Adding labels changes Prometheus time-series identity and is a breaking metric schema change. During rollout, Prometheus may temporarily contain both old and new series. Dashboards and recording rules must aggregate using explicit labels rather than relying on the former label set.</p><p>Approximate cardinality is:</p><p><code>accepted listeners x effective hostnames x path matches x valid backendRefs</code></p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Exposure series can be traced back to a specific HTTPRoute and listener.</li><li>Invalid listener attachments and ungranted cross-namespace backends are excluded.</li><li>Cardinality increases with the number of valid routing combinations.</li><li>Address discovery remains provider-independent and may temporarily yield an empty <code>ip_address</code>.</li></ul><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>Implementation is located in <code>internal/kubernetes/mapper/mapper.go</code>, <code>pkg/models/route.go</code>, and <code>internal/metrics/</code>.</p>',21)])])}const u=a(n,[["render",r]]);export{h as __pageData,u as default};
